def evolve(state: str, offsets: list[int], t: int) -> str:
    n = len(state)
    if t == 0:
        return state

    mask = (1 << n) - 1
    lamps = int(state[::-1], 2)

    active = set()
    for offset in offsets:
        offset %= n
        if offset in active:
            active.remove(offset)
        else:
            active.add(offset)

    while t and lamps and active:
        if t & 1:
            result = 0
            for offset in active:
                if offset == 0:
                    result ^= lamps
                else:
                    result ^= (lamps >> offset) | ((lamps << (n - offset)) & mask)
            lamps = result

        t >>= 1
        if t:
            doubled = set()
            for offset in active:
                offset = (2 * offset) % n
                if offset in doubled:
                    doubled.remove(offset)
                else:
                    doubled.add(offset)
            active = doubled

    if not active and t:
        lamps = 0

    return format(lamps, f"0{n}b")[::-1]
